import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the supplied
     * name and ensuring that the resolved path stays within {@code dir}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if the name resolves outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths and names that resolve outside the target directory
        Path dirPath = dir.toPath().normalize();
        Path namePath = Paths.get(name).normalize();

        // If the name is absolute or contains "..", reject it
        if (namePath.isAbsolute() || namePath.startsWith("..") || namePath.toString().contains("..")) {
            throw new IllegalArgumentException("Invalid file name: " + name);
        }

        Path targetPath = dirPath.resolve(namePath).normalize();
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Zip archives with files escaping their root directory are not allowed: " + name);
        }

        File file = targetPath.toFile();

        // Handle duplicate names by appending "-n" before the extension
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
