import java.util.Calendar;
import static java.util.Calendar.*;

public final class CronTab {

    // other methods

    /**
     * Safely sets the specified calendar field to the desired value.
     *
     * <p>This method performs rigorous validation of the target field and the
     * supplied value to prevent illegal calendar states that could otherwise
     * trigger infinite loops or other erratic behaviour in {@link #ceil}.</p>
     *
     * @param c the {@link Calendar} instance to modify
     * @param i the raw value to set (before applying {@code offset})
     * @throws IllegalArgumentException if {@code c} is {@code null},
     *         if {@code field} is not a recognised calendar field,
     *         or if the resulting value is outside the valid range for that field
     */
    void setTo(Calendar c, int i) {
        if (c == null) {
            throw new IllegalArgumentException("Calendar instance cannot be null");
        }

        // Validate that the field is a legitimate Calendar constant
        switch (field) {
            case YEAR: case MONTH: case DATE: case HOUR_OF_DAY: case MINUTE:
            case SECOND: case MILLISECOND: case DAY_OF_WEEK: case DAY_OF_MONTH:
            case DAY_OF_YEAR: case WEEK_OF_MONTH: case WEEK_OF_YEAR: case AM_PM:
            case HOUR: case ERA: case ZONE_OFFSET: case DST_OFFSET:
                break; // valid fields
            default:
                throw new IllegalArgumentException("Unsupported calendar field: " + field);
        }

        // Compute the actual value to set after applying the offset
        int value = i - offset;

        // Retrieve the legal bounds for the field
        int min = c.getMinimum(field);
        int max = c.getMaximum(field);

        // Guard against out‑of‑range values that could cause Calendar to wrap
        // unpredictably and potentially lead to infinite loops in ceil().
        if (value < min || value > max) {
            throw new IllegalArgumentException(
                String.format("Value %d for field %s is out of range [%d, %d]",
                              value, CalendarFieldName(field), min, max));
        }

        // Perform the safe assignment
        c.set(field, value);
    }

    // other methods

