import org.codehaus.plexus.logging.AbstractLogEnabled;
import org.codehaus.plexus.util.FileUtils;
import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    /**
     * Extracts a single entry from an archive into the target directory.
     *
     * <p>Security note: this method now validates the {@code entryName} to prevent
     * Zip‑Slip attacks. The resolved target file is canonicalized and verified to
     * reside within {@code dir}. If the check fails, an {@link ArchiverException}
     * is thrown.</p>
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file relative to the extraction directory
        final File targetFile = FileUtils.resolveFile(dir, entryName);

        // Canonicalize both the destination directory and the target file
        final Path canonicalDirPath = dir.getCanonicalFile().toPath();
        final Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

        // Ensure the target file is inside the destination directory
        if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException(
                    "Entry '" + entryName + "' is outside of the target directory");
        }

        // Optional: reject symlink creation if the target already exists as a symlink
        if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
            throw new ArchiverException(
                    "Attempt to overwrite existing symbolic link with regular file: " + entryName);
        }

        try {
            // Skip extraction if the file already exists and is newer
            if (!isOverwrite() && targetFile.exists() &&
                    (targetFile.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File parentDir = targetFile.getParentFile();
            if (parentDir != null) {
                parentDir.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Create a symbolic link pointing to the specified destination
                SymlinkUtils.createSymbolicLink(targetFile, new File(symlinkDestination));
            } else if (isDirectory) {
                // Ensure the directory exists
                targetFile.mkdirs();
            } else {
                // Write the file contents
                try (OutputStream out = new FileOutputStream(targetFile)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time
            targetFile.setLastModified(entryDate.getTime());

            // Apply Unix permissions if requested
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(targetFile, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + targetFile.getPath());
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }
}
