import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // other methods

    /**
     * Validates a media type token (major or subtype). A token must consist of
     * one or more characters from the set defined by RFC 7230 § 3.2.6:
     *   ALPHA / DIGIT / "!#$%&'*+-.^_`|~"
     * The wildcard "*" is also accepted as a valid token.
     *
     * @param str the token to validate
     * @return {@code true} if {@code str} is a valid token, {@code false} otherwise
     */
    protected static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard "*" as a special case
        if ("*".equals(str)) {
            return true;
        }
        // Reject any control characters (CR, LF, etc.) explicitly
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isISOControl(ch)) {
                return false;
            }
        }
        // Ensure the string matches the RFC‑compliant token pattern
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
