private static void decompress(InputStream in, byte[] out) throws IOException {
    int position = 0;
    final int total = out.length;
    while (position < total) {
        int n = in.read();
        if (n == -1) {
            throw new IOException("Unexpected end of stream");
        }
        int count = n & 0xFF;
        if (count > 128) {
            int value = in.read();
            if (value == -1) {
                throw new IOException("Unexpected end of stream");
            }
            int repeat = count & 0x7F;
            if (position + repeat > total) {
                throw new IOException("Compressed data exceeds output buffer");
            }
            byte valByte = (byte) value;
            for (int i = 0; i < repeat; i++) {
                out[position++] = valByte;
            }
        } else {
            if (position + count > total) {
                throw new IOException("Compressed data exceeds output buffer");
            }
            for (int i = 0; i < count; i++) {
                int b = in.read();
                if (b == -1) {
                    throw new IOException("Unexpected end of stream");
                }
                out[position++] = (byte) b;
            }
        }
    }
}

