import org.apache.shiro.realm.ldap.JndiLdapContextFactory;
import org.apache.shiro.realm.ldap.LdapContextFactory;
import org.apache.shiro.realm.ldap.LdapUtils;
import java.io.IOException;
import java.util.Hashtable;
import javax.naming.AuthenticationException;
import javax.naming.CommunicationException;
import javax.naming.Context;
import javax.naming.NamingException;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider {

    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and performs a
     * secure bind with the supplied credentials.  The method validates
     * the input parameters, negotiates TLS, and explicitly re‑binds
     * using the supplied principal and credentials.  Any failure to
     * authenticate results in an {@link AuthenticationException} being
     * thrown, preventing the caller from obtaining a usable context
     * with invalid credentials.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the user DN or bind name
     * @param credentials        the user password
     * @return a fully authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or
     *                          authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(
            LdapContextFactory ldapContextFactory,
            Object principal,
            Object credentials) throws NamingException {

        // Defensive checks – reject null or empty credentials early
        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }
        if (!(principal instanceof String) || !(credentials instanceof String)) {
            throw new IllegalArgumentException("Principal and credentials must be Strings");
        }
        String principalStr = ((String) principal).trim();
        String credentialsStr = ((String) credentials).trim();
        if (principalStr.isEmpty() || credentialsStr.isEmpty()) {
            throw new IllegalArgumentException("Principal and credentials must not be empty");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        try {
            // Create an unauthenticated context to negotiate TLS
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate();

            // Update environment with authentication details
            env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
            env.put(Context.SECURITY_PRINCIPAL, principalStr);
            env.put(Context.SECURITY_CREDENTIALS, credentialsStr);

            // Re‑bind using the updated environment – this performs the actual authentication
            ctx.reconnect(env);

            // Successful bind – return the context
            return ctx;
        } catch (AuthenticationException ae) {
            // Explicitly log authentication failures without leaking credentials
            securityLog.warn(withRealm("LDAP authentication failed for '%s' at '%s'", principalStr, server(jndiLdapContextFactory)));
            throw ae;
        } catch (IOException | NamingException e) {
            // Close the context if it was partially created
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to establish TLS connection with '%s': %s", server(jndiLdapContextFactory), e.getMessage()));
            throw new CommunicationException(e.getMessage(), e);
        } catch (Throwable t) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Unexpected failure to establish TLS connection with '%s': %s", server(jndiLdapContextFactory), t.getMessage()));
            throw t;
        }
    }

    // other methods
}
