    // The factory may be injected by the container; if not, we create one.
    private SAXParserFactory factory;

    // other methods

    @Activate
    protected void activate() {
        // Use the injected factory if available, otherwise create a new instance.
        if (factory == null) {
            factory = SAXParserFactory.newInstance();
        }

        // Basic configuration
        factory.setValidating(false);
        factory.setNamespaceAware(true);

        // Secure configuration to mitigate XXE attacks
        try {
            // Disallow external general entities
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            // Disallow external parameter entities
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Prevent loading external DTDs
