public class XsltRenderer implements Renderer {

    /* --------------------------------------------------------------------- *
     * Secure TransformerFactory configuration                               *
     * --------------------------------------------------------------------- */

    /**
     * A single, thread‑safe {@link TransformerFactory} instance that is
     * pre‑configured to enforce secure processing.  The factory is created
     * lazily during class initialization so that all subsequent calls to
     * {@code createTransformer} benefit from the same security settings.
     */
    private static final TransformerFactory TRANSFORMER_FACTORY = createSecureFactory();

    /**
     * Creates a {@link TransformerFactory} with the following security
     * properties enabled:
     * <ul>
     *   <li>SECURE_PROCESSING feature – prevents entity expansion attacks.</li>
     *   <li>accessExternalDTD – disallows external DTD resolution.</li>
     *   <li>accessExternalStylesheet – disallows importing external stylesheets.</li>
     * </ul>
     *
     * @return a securely configured {@link TransformerFactory}
     */
    private static TransformerFactory createSecureFactory() {
        TransformerFactory factory = TransformerFactory.newInstance();
        try {
            // Enable the standard secure processing feature
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disable external DTD access
            factory.setAttribute(
                XMLConstants.ACCESS_EXTERNAL_DTD,
                ""
            );

            // Disable external stylesheet access
            factory.setAttribute(
                XMLConstants.ACCESS_EXTERNAL_STYLESHEET,
                ""
            );
        } catch (IllegalArgumentException | UnsupportedOperationException | TransformerConfigurationException e) {
            // If the underlying implementation does not support the
            // requested features, log the issue and rethrow as a runtime
            // exception to fail fast.  In production, replace this with
            // proper logging.
            throw new RuntimeException("Failed to configure secure TransformerFactory", e);
        }
        return factory;
    }

    /* --------------------------------------------------------------------- *
     * Public API                                                             *
     * --------------------------------------------------------------------- */

    // other methods omitted for brevity

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     * The method guarantees that the template is processed under the
     * constraints defined in {@link #createSecureFactory()}.
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a compiled {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     * @throws ProcessingFailedException if the XSLT is invalid or cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
