public class Expander {

    // other methods

    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the target directory to its real (canonical) path once
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            /* ------------------------------------------------------------------
             * Sanitize the entry name before any path resolution.
             * Reject absolute paths, drive‑letter prefixes, and any leading
             * separators that could escape the target directory.
             * ------------------------------------------------------------------ */
            if (entryName == null || entryName.isEmpty()
                    || entryName.startsWith("/")
                    || entryName.startsWith("\\")
                    || entryName.matches("^[A-Za-z]:.*")) {
                throw new IOException("Invalid entry name: " + entryName);
            }

            // Normalise path separators to the platform‑independent '/' form
            entryName = entryName.replace('\\', '/');

            /* ------------------------------------------------------------------
             * Resolve the entry against the target directory and normalise.
             * The resulting path is guaranteed to be within the target directory
             * if it starts with the targetDirPath after normalization.
             * ------------------------------------------------------------------ */
            Path resolvedPath = targetDirPath.resolve(entryName).normalize();

            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "Entry would be extracted outside target dir: " + entryName);
            }

            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("Failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
