     * @return a parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private static Document parseSecurely(Object source) throws Exception {
        DocumentBuilderFactory factory = newSecureFactory();
        DocumentBuilder builder = factory.newDocumentBuilder();

        if (source instanceof InputStream) {
            return builder.parse((InputStream) source);
        } else if (source instanceof String) {
            return builder.parse(new InputSource(new StringReader((String) source)));
        } else if (source instanceof InputSource) {
            return builder.parse((InputSource) source);
        } else {
            throw new IllegalArgumentException("Unsupported source type for secure parsing: " + source.getClass());
        }
    }

