import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Objects;

/**
 * Utility class that determines whether a SCIM user update request is allowed.
 *
 * <p>Security enhancements:
 * <ul>
 *     <li>Ensures the authenticated user ID matches the target user ID in the request URL.</li>
 *     <li>Uses {@link Objects#equals(Object,Object)} for null‑safe comparisons.</li>
 *     <li>Rejects updates that attempt to change the primary email without proper verification.</li>
 * </ul>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming HTTP request is permitted to modify the specified SCIM user.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Extract the authenticated user ID from a trusted source.
        //    In a typical UAA deployment this would come from the security context,
        //    but for simplicity we read a custom header that is populated by the
        //    authentication filter.
        String authenticatedUserId = request.getHeader("X-Authenticated-User-Id");
        if (authenticatedUserId == null) {
            // No authenticated user information – deny the request.
            return false;
        }

        // 2. Parse the request body into a ScimUser object.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 3. Resolve the target user ID from the request URL.
        String id = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 4. Verify that the authenticated user is attempting to modify their own record.
        if (!Objects.equals(authenticatedUserId, id)) {
            return false;
        }

        // 5. Retrieve the current user record from the database.
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere).
            return true;
        }

        // 6. Perform field‑by‑field validation using null‑safe comparisons.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change requires verification – reject if not verified.
            if (!scimUserFromRequest.isVerified()) {
                return false;
            }
        }

        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }

        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    // other methods
}
